# Quick helper: show Claude Code API config and open CC Switch.
param(
    [switch]$OpenSwitch
)

$settingsPath = Join-Path $env:USERPROFILE ".claude\settings.json"
$dbPath = Join-Path $env:USERPROFILE ".cc-switch\cc-switch.db"

Write-Host "=== Claude Code API (live) ===" -ForegroundColor Cyan
if (Test-Path $settingsPath) {
    $settings = Get-Content $settingsPath -Raw | ConvertFrom-Json
    $base = $settings.env.ANTHROPIC_BASE_URL
    $token = $settings.env.ANTHROPIC_AUTH_TOKEN
    if ([string]::IsNullOrWhiteSpace($base) -and [string]::IsNullOrWhiteSpace($token)) {
        Write-Host "Mode: Official OAuth (no custom BASE_URL / AUTH_TOKEN in settings.json)"
    } else {
        Write-Host "ANTHROPIC_BASE_URL: $base"
        if ($token) {
            $masked = if ($token.Length -gt 8) { $token.Substring(0, 4) + "..." + $token.Substring($token.Length - 4) } else { "***" }
            Write-Host "ANTHROPIC_AUTH_TOKEN: $masked"
        }
    }
} else {
    Write-Host "No settings at $settingsPath"
}

if ($env:ANTHROPIC_BASE_URL -or $env:ANTHROPIC_AUTH_TOKEN) {
    Write-Host ""
    Write-Host "WARNING: Process env overrides settings.json. Clear with:" -ForegroundColor Yellow
    Write-Host '  Remove-Item Env:ANTHROPIC_BASE_URL, Env:ANTHROPIC_AUTH_TOKEN -ErrorAction SilentlyContinue'
}

if (Test-Path $dbPath) {
    Write-Host ""
    Write-Host "=== CC Switch (claude providers) ===" -ForegroundColor Cyan
    $py = @"
import sqlite3
c = sqlite3.connect(r"$dbPath")
for row in c.execute("SELECT name, is_current FROM providers WHERE app_type='claude' ORDER BY is_current DESC, name"):
    mark = "*" if row[1] else " "
    print(f"  {mark} {row[0]}")
"@
    python -c $py 2>$null
}

Write-Host ""
Write-Host "After switching in CC Switch: exit Claude Code completely, open a NEW terminal, then run claude." -ForegroundColor DarkGray

if ($OpenSwitch) {
    $candidates = @(
        "${env:ProgramFiles}\CC Switch\CC Switch.exe",
        "${env:LocalAppData}\Programs\CC Switch\CC Switch.exe"
    )
    $exe = $candidates | Where-Object { Test-Path $_ } | Select-Object -First 1
    if ($exe) {
        Start-Process $exe
    } else {
        Write-Host "CC Switch.exe not found. Open it from Start Menu or system tray." -ForegroundColor Yellow
    }
}

import sqlite3, json, re
db = r"C:\Users\win\AppData\Roaming\Cursor\User\globalStorage\state.vscdb"
c = sqlite3.connect(db)
rows = c.execute("SELECT key, value FROM ItemTable WHERE key LIKE '%reactivestorage%' OR key LIKE '%composer%' OR key LIKE '%agent%'").fetchall()
for key, val in rows[:8]:
    print("KEY:", key)
    if "composer" in val.lower() or "yolo" in val.lower() or "auto" in val.lower():
        for m in re.findall(r'"(yolo[^"]*|auto[^"]*|fullAuto[^"]*|useYolo[^"]*|mcp[^"]*)"[^:]*:\s*([^,}\]]+)', val[:8000], re.I):
            print(" ", m)
    print("---")

import sqlite3, json, copy

db = r"C:\Users\win\AppData\Roaming\Cursor\User\globalStorage\state.vscdb"
key = "src.vs.platform.reactivestorage.browser.reactiveStorageServiceImpl.persistentStorage.applicationUser"

c = sqlite3.connect(db)
row = c.execute("SELECT value FROM ItemTable WHERE key = ?", (key,)).fetchone()
if not row:
    print("KEY NOT FOUND")
    exit(1)

data = json.loads(row[0])
# composerState may be nested
def patch_composer_state(obj):
    if isinstance(obj, dict):
        if "yoloEnableRunEverything" in obj or "autoRun" in obj or "fullAutoRun" in obj:
            obj["yoloEnableRunEverything"] = True
            obj["fullAutoRun"] = True
            obj["autoRun"] = True
            obj["yoloMcpToolsDisabled"] = False
            obj["yoloDeleteFileDisabled"] = False
            obj["yoloOutsideWorkspaceDisabled"] = False
            obj["autoAcceptWebSearchTool"] = True
            obj["autoAcceptGenerateImageTool"] = True
            obj["autoApplyFilesOutsideContext"] = True
        for v in obj.values():
            patch_composer_state(v)
    elif isinstance(obj, list):
        for item in obj:
            patch_composer_state(item)

patch_composer_state(data)

# Also patch modes4 if present at top level
if isinstance(data, dict):
    cs = data.get("composerState") or data.get("composer", {})
    if isinstance(cs, dict):
        modes = cs.get("modes4")
        if isinstance(modes, list):
            for m in modes:
                if isinstance(m, dict):
                    m["fullAutoRun"] = True
                    m["autoRun"] = True

new_val = json.dumps(data, ensure_ascii=False)
c.execute("UPDATE ItemTable SET value = ? WHERE key = ?", (new_val, key))
c.commit()
print("PATCHED OK")
# verify
data2 = json.loads(c.execute("SELECT value FROM ItemTable WHERE key = ?", (key,)).fetchone()[0])
def find_flags(obj, path=""):
    if isinstance(obj, dict):
        for k in ("yoloEnableRunEverything", "fullAutoRun", "autoRun", "yoloMcpToolsDisabled"):
            if k in obj:
                print(f"  {path}.{k} = {obj[k]}")
        for k, v in obj.items():
            if k in ("composerState", "modes4") or "composer" in k.lower():
                find_flags(v, path + "." + k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:3]):
            find_flags(item, f"{path}[{i}]")

find_flags(data2)

